import json

filepath = "/home/ubuntu/.claude-account-3/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-8-projects-acr-vla-conformal-refinement/5a5a46e5-1871-4e2f-83a0-5ceaf4860d00/tool-results/mcp-agent-ml-research-read_registry-1779016083882.txt"

with open(filepath, 'r') as f:
    raw = json.load(f)

inner = json.loads(raw["result"])
experiments = inner["data"]["experiments"]

# Filter: eval-* + object
object_evals = {k: v for k, v in experiments.items() 
                if k.startswith("eval-") and "object" in k}

import re

def extract_info(exp_id, exp):
    spec = exp.get('spec', {})
    metrics = exp.get('metrics', {})

    # --- MODE ---
    eid = exp_id.lower()
    # Check metrics for mode first
    m_mode = metrics.get('mode', '')

    if 'vla-only' in eid or 'vla_only' in eid:
        mode = 'vla_only'
    elif 'vla-mean' in eid:
        mode = 'vla_mean'
    elif 'reconvla' in eid:
        mode = 'reconvla'
    elif 'direct-correction' in eid:
        mode = 'direct_correction'
    elif 'mag-obsonly' in eid or ('obs-only' in eid) or ('obs_only' in eid) or m_mode == 'obs_only' or 'crm_obs_only' in m_mode:
        mode = 'obs_only'
    elif 'mag-perdof' in eid or 'perdof' in eid:
        mode = 'perdof'
    elif 'argmin' in eid:
        mode = 'argmin'
    elif 'scalar' in eid:
        mode = 'scalar'
    elif 'v8-full' in eid:
        # SmolVLA baseline
        mode = 'smolvla_baseline'
    elif 'v4-default' in eid:
        # From metrics note: actual mode=crm_perdof with default norm
        mode = 'perdof'
    else:
        mode = 'unknown'

    # --- NORM ---
    norm = None
    # Check metrics for max_correction_norm
    if 'max_correction_norm' in metrics:
        norm = metrics['max_correction_norm']
    elif 'max_correction_norm' in spec:
        norm = spec['max_correction_norm']

    if norm is None:
        norm_match = re.search(r'norm(\d+)', exp_id)
        if norm_match:
            norm_str = norm_match.group(1)
            if len(norm_str) == 2:  # "02" -> 0.2
                norm = round(float(norm_str) / 10, 2)
            elif len(norm_str) == 3:  # "003" -> 0.03
                norm = round(float(norm_str) / 100, 3)
            elif len(norm_str) == 1:
                norm = round(float(norm_str) / 10, 1)

    if norm is None:
        if 'default' in eid:
            # For obs_only default, check from similar experiments
            if mode == 'perdof':
                norm = 'default(~1.42)'
            else:
                norm = 'default'
        elif mode in ('vla_only', 'vla_mean', 'reconvla', 'smolvla_baseline', 'direct_correction', 'argmin'):
            norm = 'N/A'
        elif mode == 'obs_only' and 'v4-obs-only' in eid:
            norm = 0.1  # from metrics
        elif mode == 'perdof' and 'perdof-object-seed43' in eid:
            norm = 'default'
        elif mode == 'scalar':
            norm = 'N/A'

    # --- SEED ---
    seed = spec.get('seed', metrics.get('seed', None))
    if seed is None:
        seed_match = re.search(r'seed(\d+)', exp_id)
        if seed_match:
            seed = int(seed_match.group(1))
    if seed is None:
        seed = 42  # default for experiments without explicit seed

    # --- SUCCESS RATE ---
    sr = None
    for key in ['overall_sr', 'overall_success_rate', 'avg_sr', 'success_rate']:
        if key in metrics:
            val = metrics[key]
            if isinstance(val, str):
                # Parse "19.0% (19/100)" format
                pct_match = re.match(r'([\d.]+)%', val)
                if pct_match:
                    sr = round(float(pct_match.group(1)) / 100, 2)
            elif isinstance(val, (int, float)):
                # Some are 0-1 scale, some are 0-100 (percentage)
                if val > 1:
                    sr = round(val / 100, 2)
                else:
                    sr = val
            break

    return {
        'exp_id': exp_id,
        'mode': mode,
        'norm': norm,
        'seed': seed,
        'success_rate': sr,
        'status': exp.get('status'),
        'conclusion': exp.get('conclusion', 'N/A'),
    }

results = []
for exp_id in sorted(object_evals.keys()):
    results.append(extract_info(exp_id, object_evals[exp_id]))

# Pretty-print as Python list
print("[")
for i, r in enumerate(results):
    comma = "," if i < len(results) - 1 else ""
    print(f"  {r}{comma}")
print("]")

print(f"\n\n# Summary by mode:")
from collections import defaultdict
by_mode = defaultdict(list)
for r in results:
    by_mode[r['mode']].append(r)

for mode in sorted(by_mode.keys()):
    exps = by_mode[mode]
    srs = [e['success_rate'] for e in exps if e['success_rate'] is not None]
    avg_sr = sum(srs)/len(srs) if srs else None
    print(f"  {mode}: {len(exps)} experiments, avg SR={avg_sr:.3f}" if avg_sr else f"  {mode}: {len(exps)} experiments, avg SR=N/A")
